@Component("creativeFile-handler")
@ProcessingGroup("creativeFile-processing-group")
public class CreativeFileEventHandler {
	
	// core constructor
	CreativeFileEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCreativeFileEvent
     */
    @EventHandler
    public void handle( CreateCreativeFileEvent event) {
        entityManager.persist(new CreativeFile(event.getCreativeFileId(), event.getUri(), event.getFileSizeKB(), event.getMimeType(), event.getChecksum(), event.getCreativeAsset()));
    }

    /*
     * @param	event UpdateCreativeFileEvent
     */
    @EventHandler
    public CreativeFile handle( UpdateCreativeFileEvent event) {
    	entityManager.merge(new CreativeFile(event.getCreativeFileId(), event.getUri(), event.getFileSizeKB(), event.getMimeType(), event.getChecksum(), event.getCreativeAsset()));
    }
    
    /*
     * @param	event DeleteCreativeFileEvent
     */
    @EventHandler
    public void on( DeleteCreativeFileEvent event) {
    	CreativeFile entity = new CreativeFile();
   
    	// ------------------------------------------
    	// apply the CreativeFileId
    	// ------------------------------------------
    	entity.setCreativeFileId( event.getCreativeFileId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CreativeFileRepository creativeFileEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CreativeFileEventHandler.class.getName());

}
